document.addEventListener("DOMContentLoaded",()=>{const dropdownHeads=document.querySelectorAll(".drop-head");dropdownHeads.forEach(head=>{head.addEventListener("click",()=>{const parentDropdown=head.closest(".dropdown"),body=parentDropdown.querySelector(".drop-body"),arrow=parentDropdown.querySelector(".drop-arrow"),isOpen=body.classList.toggle("open");arrow.classList.toggle("open",isOpen)})})});